/// `POCKET_*` values for the Rogue pocket layout, named after the game's own
/// `POCKET_*` constants so the editor reasons about bag runs instead of magic
/// numbers. Not every pocket is referenced from production code (some only from
/// tests), which is why each carries its own `allow(dead_code)`: they are the
/// game's vocabulary, kept whole rather than trimmed to what one call site
/// uses.
#[allow(dead_code)]
pub const POCKET_NONE: u8 = 0;
#[allow(dead_code)]
pub const POCKET_ITEMS: u8 = 1;
#[allow(dead_code)]
pub const POCKET_HELD_ITEMS: u8 = 2;
#[allow(dead_code)]
pub const POCKET_MEDICINE: u8 = 3;
#[allow(dead_code)]
pub const POCKET_STONES: u8 = 4;
#[allow(dead_code)]
pub const POCKET_POKE_BALLS: u8 = 5;
#[allow(dead_code)]
pub const POCKET_TM_HM: u8 = 6;
#[allow(dead_code)]
pub const POCKET_BERRIES: u8 = 7;
#[allow(dead_code)]
pub const POCKET_POKEBLOCK: u8 = 8;
#[allow(dead_code)]
pub const POCKET_KEY_ITEMS: u8 = 9;

